    // \u05E6\u05D1\u05E2 \u05EA\u05E6\u05D5\u05D2\u05D4 \u05D4\u05E7\u05E1\u05D3\u05E6\u05D9\u05DE\u05DC\u05D9, \u05DC\u05DE\u05E9\u05DC "#f87171" \u2014 \u05D0\u05D5\u05E4\u05E6\u05D9\u05D5\u05E0\u05DC\u05D9
