// \u05D0\u05D6 \u05D4\u05D4\u05DB\u05E8\u05D6\u05D4 \u05D2\u05E8\u05D4 \u05D1\u05DE\u05D5\u05D3\u05D5\u05DC \u05E9\u05E0\u05D8\u05E2\u05DF \u05E8\u05D0\u05E9\u05D5\u05DF.)
