    // \u05DC\u05E2\u05D5\u05DC\u05DD \u05DC\u05D0 \u05D4\u05E1\u05D9\u05E1\u05DE\u05D4 \u05E2\u05E6\u05DE\u05D4 \u2014 \u05E8\u05E7 \u05D4\u05EA\u05D5\u05E6\u05E8 \u05E9\u05DC PBKDF2 (\u05E6\u05E2\u05D3 5.4)
