// \u05DB\u05D9 \u05D4\u05D5\u05D0 \u05D7\u05DC\u05E7 \u05DE\u05D4\u05E9\u05E4\u05D4 \u05D4\u05DE\u05E9\u05D5\u05EA\u05E4\u05EA \u05E9\u05DC \u05E9\u05E0\u05D9 \u05D4\u05E6\u05D3\u05D3\u05D9\u05DD.
export type UserRole = 'Member' | 'Admin';

/** \u05D4\u05DE\u05E8\u05D0\u05D4 \u05E9\u05DC UserResponse */
export interface AuthUser {
  id: number;
  email: string;
  displayName: string;
  role: UserRole;
}

/** \u05D4\u05DE\u05E8\u05D0\u05D4 \u05E9\u05DC AuthResponse \u2014 \u05D4\u05D6\u05D5\u05D2 \u05D4\u05DE\u05DC\u05D0 + \u05DE\u05EA\u05D9 \u05D4-access \u05E4\u05D2 */
export interface AuthSession {
  accessToken: string;
  refreshToken: string;
  expiresAtUtc: string;
  user: AuthUser;
}
