    /// <summary>\u05E6\u05D9\u05E8\u05D5\u05E3 \u05D7\u05D1\u05E8 \u05E7\u05D9\u05D9\u05DD \u05D1\u05DE\u05E2\u05E8\u05DB\u05EA \u05DC\u05E4\u05E8\u05D5\u05D9\u05E7\u05D8. \u05DE\u05D7\u05D6\u05D9\u05E8 false \u05D0\u05DD \u05DB\u05D1\u05E8 \u05D7\u05D1\u05E8.</summary>
