// \u05D4\u05E7\u05E8\u05E0\u05D5\u05EA \u05D0\u05D2\u05E8\u05D2\u05E6\u05D9\u05D4 \u2014 \u05D1\u05D3\u05D9\u05D5\u05E7 \u05DE\u05D4 \u05E9\u05D4\u05D3\u05E9\u05D1\u05D5\u05E8\u05D3 \u05E6\u05E8\u05D9\u05DA \u05DB\u05D3\u05D9 \u05DC\u05E6\u05D9\u05D9\u05E8. \u05D7\u05D9\u05D5\u05EA \u05D1-Core/Common
// \u05DB\u05DE\u05D5 ProjectSummary \u05D5-SearchResults: POCO \u05D7\u05D5\u05E6\u05D9-\u05E9\u05DB\u05D1\u05D5\u05EA, \u05DC\u05D0 \u05D9\u05E9\u05D5\u05D9\u05D5\u05EA. \u05DB\u05DC \u05E1\u05E4\u05D9\u05E8\u05D4
