namespace TaskForge.Api.Contracts;

// \u05EA\u05E9\u05D5\u05D1\u05EA \u05D4-feed: \u05D0\u05D9\u05E8\u05D5\u05E2 \u05DE\u05E9\u05D5\u05D8\u05D7 \u05E2\u05DD \u05E9\u05DD \u05D4\u05DE\u05D1\u05E6\u05E2. \u05D4\u05D9\u05E9\u05D5\u05EA ActivityEvent \u05DE\u05D7\u05D6\u05D9\u05E7\u05D4 FK
