namespace TaskForge.Core.Abstractions;

// seam \u05D4\u05D0\u05D2\u05E8\u05D2\u05E6\u05D9\u05D4: "\u05DB\u05DB\u05D4 \u05E9\u05D5\u05D0\u05DC\u05D9\u05DD \u05D0\u05EA \u05D4-DB \u05E1\u05D9\u05DB\u05D5\u05DD \u05E9\u05DC \u05E4\u05E8\u05D5\u05D9\u05E7\u05D8". \u05D4\u05DE\u05D9\u05DE\u05D5\u05E9 (GROUP BY)
